    SELECT SEQ_RSRV_ID.NEXTVAL FROM DUAL

INSERT INTO TB_CONF_RM_RSRV (
    RSRV_ID
    , CONF_RM_ID
    , RSRV_EMP_ID
    , RSRV_PURPS
    , BEGIN_DT
    , END_DT
    , DEL_YN
    , INTG_RSRV_YN
) VALUES (
    #{rsrvId}
    , #{confRmId}
    , #{rsrvEmpId}
    , #{rsrvPurps}
    , #{beginDt}
    , #{endDt}
    , 'N'
    , #{intgRsrvYn}
)

mapper.update:
UPDATE TB_CONF_RM_RSRV
SET DEL_YN = 'Y'
WHERE RSRV_ID = #{rsrvId}

mapper.select:
SELECT COUNT(*)
FROM TB_CONF_RM_RSRV
WHERE CONF_RM_ID = #{confRmId}
  AND DEL_YN = 'N'
  AND RSRV_ID != #{rsrvId}
  AND BEGIN_DT   <  #{endDt}
  AND END_DT     >  #{beginDt}
